def num_comm_div(a, b):
    divisors_a = set()
    for i in range(1, a+1):
        if a % i == 0:
            divisors_a.add(i)
    divisors_b = set()
    for j in range(1, b+1):
        if b % j == 0:
            divisors_b.add(j)
    common_divisors = divisors_a.intersection(divisors_b)
    return max(common_divisors)

def num_comm_div(a, b):
